// ============================================================
//  공정 흐름 SCM — In-memory Database
// ============================================================
import bcrypt from 'bcryptjs';

// ─── User ───────────────────────────────────────────────────
export interface User {
  id: string;
  username: string;
  password: string;
  name: string;
  email: string;
  role: 'admin' | 'user';
  department: string;
  status: 'active' | 'inactive';
  createdAt: string;
  createdBy: string;
}

// ─── Process (공정 정의) ──────────────────────────────────────
export interface ProcessStep {
  stepNo: number;          // 단계 번호 (#10, #20, #30 … 10 단위, 중간 삽입 시 #15 등 가능)
  name: string;            // 공정 단계명 (예: 가공, 도금(Ch), 검사)
  company: string;         // 담당 업체 (예: DK테크, P품질)
  description: string;     // 추가 설명
  stdTime: number;         // 표준 소요 시간 (분)
  equipmentId: string;
  equipmentName: string;
}

export interface Process {
  id: string;
  processCode: string;     // 공정 코드 (e.g. PROC-0001)
  pn: string;              // 업체 P/N (품번) — 주요 검색 키
  matCode: string;         // 자재코드
  name: string;            // 품명
  category: string;        // 분류
  customer: string;        // 고객사
  project: string;         // 사업명
  description: string;     // 설명
  steps: ProcessStep[];    // 공정 단계 목록 (stepNo 순 정렬)
  status: 'active' | 'inactive';
  createdAt: string;
  createdBy: string;
}

// ─── WorkOrder (작업 지시) ────────────────────────────────────
export interface StepProgress {
  stepNo: number;
  stepName: string;
  status: 'pending' | 'in_progress' | 'completed' | 'paused' | 'skipped';
  startedAt: string;
  completedAt: string;
  progressRate: number;
  workerName: string;
  note: string;
  defectCount: number;
}

export interface WorkOrder {
  id: string;
  workOrderNo: string;
  pn: string;              // 업체 P/N (품번) — 공정에서 복사
  processId: string;
  processName: string;
  productName: string;
  targetQty: number;
  completedQty: number;
  defectQty: number;
  priority: 'urgent' | 'high' | 'normal' | 'low';
  status: 'pending' | 'in_progress' | 'completed' | 'paused' | 'cancelled';
  progressRate: number;
  currentStep: number;
  steps: StepProgress[];
  plannedStart: string;
  plannedEnd: string;
  customerDueDate: string; // 고객사 납기일 (customer delivery due date)
  actualStart: string;
  actualEnd: string;
  assignedTo: string;
  createdBy: string;
  notes: string;
  createdAt: string;
}

// ─── Material (자재) ──────────────────────────────────────────
export interface Material {
  id: string;
  materialCode: string;
  name: string;
  category: string;
  unit: string;
  stockQty: number;
  minQty: number;
  unitCost: number;
  supplierId: string;
  supplierName: string;
  location: string;
  status: 'normal' | 'low' | 'out';
  lastUpdated: string;
}

// ─── Equipment (설비) ─────────────────────────────────────────
export interface Equipment {
  id: string;
  equipmentCode: string;
  name: string;
  category: string;
  location: string;
  status: 'running' | 'idle' | 'maintenance' | 'breakdown';
  utilizationRate: number;
  lastMaintenance: string;
  nextMaintenance: string;
  assignedProcess: string;
}

